@spec patternEditor_writethrough_spec  src=tests/specs/patternEditor_writethrough_spec.lua  loc=271  sha=5c74b87  cases=9
@harness   mk, reaper.GetMediaItemTake_Track

# Intent
  design/fx-patterns.md P3.5: write-through commit; curve normalises pb thousandths back to bipolar.
  Drives the real edit -> flush -> rebuild -> write-through path against a fake imgui.

# Helpers
  @fn keyId(name)  @ 13-22
  @fn setKeys(keys, mods)  @ 37-40
  @fn loadPE(deps)  @ 46-52
  @fn notesBody()  @ 60-68
  @fn openNotesBody()  @ 71-79
      -- An OPEN first note followed by a finite one: readback must clip the open tail to the successor.
  @fn polyNotesBody()  @ 83-91
      -- Two overlapping notes on distinct lanes: a poly open keeps them apart; a mono open crushes them
      -- onto lane 1, where the readback clip serialises them as a monophonic run.
  @fn curveBody()  @ 93-102
  @fn ccCurveBody()  @ 105-114
      -- cc-domain curve: points ride a fixed scratch cc verbatim (0..127), no normalisation.
  @fn withEditor(harness, body, poly)  @ 118-124
      -- Open the editor on `body`, capturing each write-through commit; get() reads the latest.
      -- `poly` rides into pe:open: true authors overlapping lanes, absent/false pins everything to lane 1.
  @fn pressDelete(pe)  @ 127-130
      -- Delete the event under the (default row-0) cursor via the real dispatch path.
  @fn approx(a, b)  @ 132

# Cases
  @case 'a checkout edit writes through the commit callback, stripped to the whitelist'  [harness]  @ 136-150
  @case 'readback clips an OPEN note to its successor onset, not the loop length'  [harness]  @ 154-165
  @case 'a curve edit persists as normalised bipolar points, not raw thousandths'  [harness]  @ 169-184
  @case 'a cc-domain curve persists its points verbatim, echoing the domain'  [harness]  @ 188-204
  @case 'Enter commits: the edit stays in the store'  [harness]  @ 208-215
  @case 'Esc cancels: the store is restored to the open snapshot'  [harness]  @ 219-228
  @case 'close does not clobber the committed body via the unbind rebuild'  [harness]  @ 232-239
  @case 'a poly open keeps each authored lane through readback'  [harness]  @ 243-256
  @case 'the same body opened mono flattens every note onto lane 1'  [harness]  @ 260-269

